const fs=require('fs');
(async()=>{
 const targets=await (await fetch('http://127.0.0.1:9222/json')).json();
 const page=targets.find(t=>t.type==='page'); if(!page) throw Error('No Chrome page');
 const ws=new WebSocket(page.webSocketDebuggerUrl); await new Promise((r,j)=>{ws.onopen=r;ws.onerror=j});
 let id=0, pending=new Map(); ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}};
 const evalJS=expr=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method:'Runtime.evaluate',params:{expression:expr,awaitPromise:true,returnByValue:true}}))});
 await evalJS("document.getElementById('startBtn').click(); document.getElementById('viewBtn').click(); true");
 await new Promise(r=>setTimeout(r,1400));
 const result=await evalJS("document.getElementById('game').toDataURL('image/jpeg',.82).split(',')[1]");
 const b64=result.result.result.value;fs.writeFileSync('/tmp/opencode/game-check.jpg',Buffer.from(b64,'base64'));
 console.log('saved first-person canvas JPEG',fs.statSync('/tmp/opencode/game-check.jpg').size,'bytes');ws.close();
})().catch(e=>{console.error(e);process.exit(1)});
